    AND NOT EXISTS (
        SELECT 1 FROM public.universe u
        WHERE u.symbol = missing AND u.isin IS NULL AND u.data_quality = 'UNRESOLVED'
      )
    AND NOT EXISTS (
        SELECT 1 FROM public.universe u
        WHERE u.symbol = missing AND u.data_quality = 'NAME_MISMATCH'
